    /**
     * @payload
     * @property {string} [componentType=series]
     * @property {number} [dx]
     * @property {number} [dy]
     * @property {number} [zoom]
     * @property {number} [totalZoom] The accumulated zoom of the view after this roam.
     * @property {number} [originX]
     * @property {number} [originY]
     */
    registers.registerAction({
        type: 'geoRoam',
        event: 'geoRoam',
        update: 'updateTransform'
    }, function (payload: RoamPayload, ecModel: GlobalModel, api: ExtensionAPI) {
        const componentType = payload.componentType || 'series';
        // The accumulated zoom of the view after this roam, which is exposed
        // on the `georoam` event as `totalZoom`.
        let totalZoom = payload.totalZoom;

        ecModel.eachComponent(
            { mainType: componentType, query: payload },
            function (componentModel: GeoModel | MapSeries) {
                const geo = componentModel.coordinateSystem;
                if (geo.type !== 'geo') {
                    return;
                }

                const res = updateCenterAndZoom(
                    geo, payload, (componentModel as GeoModel).get('scaleLimit'), api
                );

                totalZoom = res.zoom;

                componentModel.setCenter
                    && componentModel.setCenter(res.center);

                componentModel.setZoom
                    && componentModel.setZoom(res.zoom);

                // All map series with same `map` use the same geo coordinate system
                // So the center and zoom must be in sync. Include the series not selected by legend
                if (componentType === 'series') {
                    each((componentModel as MapSeries).seriesGroup, function (seriesModel) {
                        seriesModel.setCenter(res.center);
                        seriesModel.setZoom(res.zoom);
                    });
                }
            }
        );

        // Keep all the fields of the payload so that the existing listeners of
        // the `georoam` event are not affected, and expose `totalZoom` besides.
        return zrUtil.extend(zrUtil.extend({} as RoamPayload, payload), {
            totalZoom: totalZoom
        });
    });
}

