        properties: { name: 'AAA' },
        geometry: {
            type: 'Polygon',
            coordinates: [[[0, 0], [0, 10], [10, 10], [10, 0], [0, 0]]]
        }
    }, {
        type: 'Feature',
        properties: { name: 'BBB' },
        geometry: {
            type: 'Polygon',
            coordinates: [[[10, 0], [10, 10], [20, 10], [20, 0], [10, 0]]]
        }
    }]
};

describe('geoRoam', function () {

    let chart: EChartsType;

    beforeEach(function () {
        registerMap('ut-geo-roam', geoJson as any);
        chart = createChart();
    });

    afterEach(function () {
        removeChart(chart);
    });

    it('georoam event should expose the accumulated `totalZoom`', function () {
        chart.setOption({
            geo: {
                map: 'ut-geo-roam',
                roam: true
            }
        });

        const events: any[] = [];
        chart.on('georoam', function (params: any) {
            events.push(params);
        });

        chart.dispatchAction({
            type: 'geoRoam',
            componentType: 'geo',
            geoIndex: 0,
            zoom: 2,
            originX: 250,
            originY: 200
        });

        expect(events.length).toEqual(1);
        // Existing fields should keep working.
        expect(events[0].zoom).toEqual(2);
        expect(events[0].originX).toEqual(250);
        expect(events[0].totalZoom).toBeCloseTo(2, 5);

        // The accumulated zoom tracks successive zoom operations.
        chart.dispatchAction({
            type: 'geoRoam',
            componentType: 'geo',
            geoIndex: 0,
            zoom: 1.5,
            originX: 250,
            originY: 200
        });

        expect(events.length).toEqual(2);
        expect(events[1].zoom).toEqual(1.5);
        expect(events[1].totalZoom).toBeCloseTo(3, 5);
    });

    it('georoam event on pan should not break existing fields', function () {
        chart.setOption({
            geo: {
                map: 'ut-geo-roam',
                roam: true
            }
        });

        const events: any[] = [];
        chart.on('georoam', function (params: any) {
            events.push(params);
        });

        chart.dispatchAction({
            type: 'geoRoam',
            componentType: 'geo',
            geoIndex: 0,
            dx: 10,
            dy: 20
        });

        expect(events.length).toEqual(1);
        expect(events[0].dx).toEqual(10);
        expect(events[0].dy).toEqual(20);
        expect(events[0].totalZoom).toBeCloseTo(1, 5);
    });
});

