import { EChartsType, registerMap } from '../../../../../src/echarts.all';
import { createChart, getGraphicElements, removeChart } from '../../../core/utHelper';
import { getECData } from '../../../../../src/util/innerStore';
import Displayable from 'zrender/src/graphic/Displayable';
import Group from 'zrender/src/graphic/Group';

function makeFeature(name: string, x0: number, echartsStyle?: any) {
    const feature = {
        type: 'Feature',
        properties: {
            name: name
        },
        geometry: {
            type: 'Polygon',
            coordinates: [[[x0, 0], [x0, 10], [x0 + 10, 10], [x0 + 10, 0], [x0, 0]]]
        }
    } as any;
    if (echartsStyle) {
        feature.properties.echartsStyle = echartsStyle;
    }
    return feature;
}

function getRegionPathStyle(chart: EChartsType, regionName: string): Displayable['style'] {
    const els = getGraphicElements(chart, 'geo', 0);
    for (let i = 0; i < els.length; i++) {
        const eventData = getECData(els[i]).eventData;
        if (eventData && eventData.name === regionName) {
            const path = (els[i] as Group).childAt(0) as Displayable;
            return path && path.style;
        }
    }
    return null;
}

describe('geoJSON region style', function () {

    let chart: EChartsType;

    beforeEach(function () {
        chart = createChart();
    });

    afterEach(function () {
        removeChart(chart);
    });

    it('should use `properties.echartsStyle` as the default region style', function () {
        registerMap('ut-geojson-style', {
            type: 'FeatureCollection',
            features: [
                makeFeature('AAA', 0, { itemStyle: { areaColor: 'red' } }),
                makeFeature('BBB', 10)
            ]
        } as any);

        chart.setOption({
            geo: {
                map: 'ut-geojson-style'
            }
        });

        expect(getRegionPathStyle(chart, 'AAA').fill).toEqual('red');
        // Region without `echartsStyle` keeps rendering as before.
        expect(getRegionPathStyle(chart, 'BBB').fill).toEqual('#eee');
    });

    it('user specified region option should override `properties.echartsStyle`', function () {
        registerMap('ut-geojson-style-2', {
            type: 'FeatureCollection',
            features: [
                makeFeature('AAA', 0, {
                    itemStyle: { areaColor: 'red', borderColor: 'green' }
                }),
                makeFeature('BBB', 10)
            ]
        } as any);

        chart.setOption({
            geo: {
                map: 'ut-geojson-style-2',
                regions: [{
                    name: 'AAA',
                    itemStyle: { areaColor: 'blue' }
                }]
            }
        });

        const style = getRegionPathStyle(chart, 'AAA');
        expect(style.fill).toEqual('blue');
        // Not specified by user, so the GeoJSON style is still the default.
        expect(style.stroke).toEqual('green');
    });

    it('GeoJSON without `echartsStyle` should render exactly as before', function () {
        registerMap('ut-geojson-style-3', {
            type: 'FeatureCollection',
            features: [
                makeFeature('AAA', 0),
                makeFeature('BBB', 10)
            ]
        } as any);

        chart.setOption({
            geo: {
                map: 'ut-geojson-style-3'
            }
        });

        expect(getRegionPathStyle(chart, 'AAA').fill).toEqual('#eee');
        expect(getRegionPathStyle(chart, 'AAA').stroke).toEqual('#444');
        expect(getRegionPathStyle(chart, 'BBB').fill).toEqual('#eee');
    });
});

