 * be overridden by `regionOption`. Neither of the inputs is modified.
 */
export function applyRegionStyleAsDefault<T extends object>(
    regionOption: T,
    defaultStyle: RegoinOption
): T {
    if (!defaultStyle) {
        return regionOption;
    }
    // `merge` clones the values of the source, so the inputs are not modified.
    const target = zrUtil.clone(defaultStyle) as T;
    return zrUtil.isObject(target) && zrUtil.isObject(regionOption) && !zrUtil.isArray(regionOption)
        ? zrUtil.merge(target, regionOption, true)
        : regionOption;
}

