getRegionModel(regionName: string): Model<MapDataItemOption> {
    const data = this.getData();
    const itemModel = data.getItemModel<MapDataItemOption>(data.indexOfName(regionName));

    const geoJSONRegionStyle = this._geoJSONRegionStyleMap
        && this._geoJSONRegionStyleMap.get(regionName);
    if (!geoJSONRegionStyle) {
        return itemModel;
    }

    // The style declared in the original GeoJSON data is the default style
    // of this region, which can be overridden by the data item specified
    // by users. Synthesize a region model for it, so that it also works
    // for the regions that do not exist in `data`.
    const cached = this._regionModelMap.get(regionName);
    if (cached) {
        return cached;
    }
    return this._regionModelMap.set(regionName, new Model(
        applyRegionStyleAsDefault(itemModel.option, geoJSONRegionStyle),
        this,
        this.ecModel
    ));
}

