/**
 * The style declared in the original GeoJSON data by
 * `feature.properties.echartsStyle` is used as the default style of that
 * region. The region option specified by users has higher priority.
 */
function applyGeoJSONRegionStyleAsDefault(
    regionModel: Model<RegoinOption> | Model<MapDataItemOption>,
    region: GeoJSONRegion,
    mapOrGeoModel: MapOrGeoModel
): Model<RegoinOption> | Model<MapDataItemOption> {
    const echartsStyle = region.echartsStyle;
    if (!echartsStyle) {
        return regionModel;
    }
    // `merge` clones the values of the source, so neither the GeoJSON data nor
    // the user specified option will be modified here.
    const option = zrUtil.merge(
        zrUtil.clone(echartsStyle),
        regionModel && regionModel.option,
        true
    );
    return new Model(
        option,
        (regionModel && regionModel.parentModel) || mapOrGeoModel,
        mapOrGeoModel.ecModel
    ) as Model<RegoinOption>;
}

