function makeFeature(name: string, x0: number, echartsStyle?: any) {
    const feature = {
        type: 'Feature',
        properties: {
            name: name
        },
        geometry: {
            type: 'Polygon',
            coordinates: [[[x0, 0], [x0, 10], [x0 + 10, 10], [x0 + 10, 0], [x0, 0]]]
        }
    } as any;
    if (echartsStyle) {
        feature.properties.echartsStyle = echartsStyle;
    }
    return feature;
}

function getRegionPathStyle(chart: EChartsType, regionName: string): Displayable['style'] {
    const seriesModel = getECModel(chart).getSeriesByIndex(0) as MapSeries;
    const data = seriesModel.getData();
    const el = data.getItemGraphicEl(data.indexOfName(regionName));
    const path = el && (el as Group).childAt(0) as Displayable;
    return path && path.style;
}

