                makeFeature('AAA', 0, {
                    itemStyle: { areaColor: 'red', borderColor: 'green' }
                }),
                makeFeature('BBB', 10)
            ]
        } as any);

        chart.setOption({
            series: [{
                type: 'map',
                map: 'ut-map-geojson-style-2',
                data: [{
                    name: 'AAA',
                    value: 100,
                    itemStyle: { areaColor: 'blue' }
                }]
            }]
        });

        const style = getRegionPathStyle(chart, 'AAA');
        expect(style.fill).toEqual('blue');
        // Not specified in the data item, so the GeoJSON style is the default.
        expect(style.stroke).toEqual('green');
    });

    it('map without `echartsStyle` should render exactly as before', function () {
        registerMap('ut-map-geojson-style-3', {
            type: 'FeatureCollection',
            features: [
                makeFeature('AAA', 0),
                makeFeature('BBB', 10)
            ]
        } as any);

        chart.setOption({
            series: [{
                type: 'map',
                map: 'ut-map-geojson-style-3',
                data: [{ name: 'BBB', value: 100 }]
            }]
        });

        expect(getRegionPathStyle(chart, 'AAA').fill).toEqual('#eee');
        expect(getRegionPathStyle(chart, 'AAA').stroke).toEqual('#444');
    });

    it('`echartsStyle` should also work for labels of regions absent from data', function () {
        registerMap('ut-map-geojson-style-4', {
            type: 'FeatureCollection',
