        chart.setOption({
            series: [{
                type: 'map',
                map: 'ut-map-geojson-style-4',
                data: [{ name: 'BBB', value: 100 }]
            }]
        });

        const seriesModel = getECModel(chart).getSeriesByIndex(0) as MapSeries;
        const data = seriesModel.getData();
        const el = data.getItemGraphicEl(data.indexOfName('AAA'));
        const label = (el as Group).childAt(0).getTextContent();
        expect(label).toBeTruthy();
        expect(label.ignore).toBeFalsy();
        expect(label.style.fill).toEqual('red');
    });

    // Unused elements should not throw when styles are declared in geo.regions
    // together with the GeoJSON style.
    it('should work when geo component hosts the map series', function () {
        registerMap('ut-map-geojson-style-5', {
            type: 'FeatureCollection',
            features: [
                makeFeature('AAA', 0, { itemStyle: { areaColor: 'red' } }),
                makeFeature('BBB', 10)
            ]
        } as any);

        chart.setOption({
            geo: {
                map: 'ut-map-geojson-style-5'
            },
            series: [{
                type: 'map',
                geoIndex: 0,
                data: [{ name: 'BBB', value: 100 }]
            }]
        });

        const els = getGraphicElements(chart, 'geo', 0);
        expect(els.length).toBeGreaterThan(0);
        const geoModel = getECModel(chart).getComponent('geo', 0) as any;
        expect(geoModel.getRegionModel('AAA').get(['itemStyle', 'areaColor'])).toEqual('red');
    });
});

