/**
 * A silent region keeps its visual but does not respond to any mouse/touch
 * event, and thus no interactive affordance (hover emphasis, select, tooltip)
 * is displayed on it. The other regions are not affected.
 * Notice: this also makes the label of this region silent, because zrender
 * checks `silent` on the host el and all of its ancestors.
 */
function resetSilentForRegion(
    el: Element,
    regionModel: RegionModel
): void {
    // @ts-ignore FIXME:TS fix the "compatible with each other"?
    const silent = regionModel.get('silent');
    if (silent != null) {
        el.silent = !!silent;
    }
}

